-- 013_situations_fix.sql
-- 012 stored situations activities_json as a bare array (parse failed →
-- empty lessons → lesson player stuck loading). 012 already applied on
-- existing installs and won't re-run, so re-apply the corrected lessons
-- here (object form {"activities":[...]}). INSERT OR REPLACE overwrites.

INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (201, 101, 'Pedir en un restaurante', '注文する', 'Entra, pide el menú y ordena con cortesía.', 6, 1, 1, '{"activities":[{"id":"r1","kind":"intro_vocab","word":"メニュー","reading":"めにゅー","meaning":"menú","example":"メニューをください。"},{"id":"r2","kind":"intro_vocab","word":"水","reading":"みず","meaning":"agua","example":"水をください。"},{"id":"r3","kind":"intro_grammar","title":"～をください","pattern":"N を ください","explanation":"Pides algo con cortesía: ''déme N, por favor''.","example":{"jp":"水をください。","reading":"みずをください","meaning":"Agua, por favor."}},{"id":"r4","kind":"listening","textJp":"いらっしゃいませ。","voice":"Kyoko","prompt":"El mesero te recibe. ¿Qué significa?","options":["Bienvenido","Gracias","Hasta luego"],"correctIndex":0,"explanation":"いらっしゃいませ es el saludo de bienvenida en tiendas y restaurantes."},{"id":"r5","kind":"quiz","prompt":"¿Cómo pides el menú con cortesía?","options":["メニューをください。","メニューです。","メニューですか。"],"correctIndex":0,"explanation":"N を ください = ''déme N, por favor''."},{"id":"r6","kind":"speaking","textJp":"すみません、メニューをください。","reading":"すみません、めにゅーをください","meaning":"Disculpe, el menú por favor.","voice":"Kyoko"},{"id":"r7","kind":"write_sentence","prompt":"Pide agua, por favor.","hint":"水 + を + ください","accepted":["水をください","水をください。","みずをください"],"explanation":"水 (みず) = agua. N を ください para pedir con cortesía."},{"id":"r8","kind":"summary","learned":["メニュー (menú)","水 (agua)","～をください (pedir con cortesía)","いらっしゃいませ (bienvenida)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (202, 102, 'Tu primera presentación', '自己紹介', 'Saluda, di tu nombre y preséntate.', 6, 1, 1, '{"activities":[{"id":"p1","kind":"intro_vocab","word":"名前","reading":"なまえ","meaning":"nombre","example":"名前は アナ です。"},{"id":"p2","kind":"intro_grammar","title":"はじめまして","pattern":"はじめまして。… です。","explanation":"Frase fija para presentarte: ''Mucho gusto''.","example":{"jp":"はじめまして。アナです。","reading":"はじめまして。あなです","meaning":"Mucho gusto. Soy Ana."}},{"id":"p3","kind":"quiz","prompt":"¿Cómo dices ''Soy Ana''?","options":["私はアナです。","アナをください。","アナですか。"],"correctIndex":0,"explanation":"X は Y です = ''X es Y''."},{"id":"p4","kind":"listening","textJp":"どうぞ よろしく おねがいします。","voice":"Otoya","prompt":"Cierre típico de una presentación. ¿Qué expresa?","options":["Encantado / cuento contigo","Buenas noches","Lo siento"],"correctIndex":0,"explanation":"よろしくおねがいします se dice al conocer a alguien."},{"id":"p5","kind":"speaking","textJp":"はじめまして。どうぞ よろしく おねがいします。","reading":"はじめまして。どうぞ よろしく おねがいします","meaning":"Mucho gusto. Encantado de conocerte.","voice":"Otoya"},{"id":"p6","kind":"write_sentence","prompt":"Escribe: Soy estudiante.","hint":"私 + は + 学生 + です","accepted":["私は学生です","私は学生です。","わたしはがくせいです"],"explanation":"私 (わたし) = yo, 学生 (がくせい) = estudiante."},{"id":"p7","kind":"summary","learned":["名前 (nombre)","はじめまして (mucho gusto)","X は Y です","よろしくおねがいします"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (203, 103, 'Comprar en la tienda', '買い物', 'Pregunta precios y paga en una tienda.', 6, 1, 1, '{"activities":[{"id":"s1","kind":"intro_vocab","word":"いくら","reading":"いくら","meaning":"cuánto (precio)","example":"いくらですか。"},{"id":"s2","kind":"intro_vocab","word":"これ","reading":"これ","meaning":"esto","example":"これをください。"},{"id":"s3","kind":"intro_grammar","title":"いくらですか","pattern":"N は いくらですか","explanation":"Preguntas el precio: ''¿cuánto cuesta N?''.","example":{"jp":"これはいくらですか。","reading":"これはいくらですか","meaning":"¿Cuánto cuesta esto?"}},{"id":"s4","kind":"listening","textJp":"さんびゃくえんです。","voice":"Kyoko","prompt":"El precio que escuchas es…","options":["300 yenes","3.000 yenes","13 yenes"],"correctIndex":0,"explanation":"さんびゃく = 300, えん = yen."},{"id":"s5","kind":"quiz","prompt":"¿Cómo preguntas el precio de esto?","options":["これはいくらですか。","これをください。","これはなんですか。"],"correctIndex":0,"explanation":"いくらですか = ''¿cuánto cuesta?''."},{"id":"s6","kind":"speaking","textJp":"これはいくらですか。","reading":"これはいくらですか","meaning":"¿Cuánto cuesta esto?","voice":"Kyoko"},{"id":"s7","kind":"write_sentence","prompt":"Pide esto, por favor.","hint":"これ + を + ください","accepted":["これをください","これをください。"],"explanation":"これ = esto; N を ください para pedirlo."},{"id":"s8","kind":"summary","learned":["いくら (cuánto)","これ (esto)","いくらですか (¿cuánto cuesta?)","円 (yen)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (204, 104, 'Tomar el tren', '駅で', 'Pregunta direcciones y ubica la estación.', 6, 1, 1, '{"activities":[{"id":"e1","kind":"intro_vocab","word":"駅","reading":"えき","meaning":"estación","example":"駅はどこですか。"},{"id":"e2","kind":"intro_vocab","word":"電車","reading":"でんしゃ","meaning":"tren","example":"電車に のります。"},{"id":"e3","kind":"intro_grammar","title":"～はどこですか","pattern":"N は どこですか","explanation":"Preguntas dónde está algo.","example":{"jp":"駅はどこですか。","reading":"えきはどこですか","meaning":"¿Dónde está la estación?"}},{"id":"e4","kind":"listening","textJp":"つぎは とうきょうです。","voice":"Otoya","prompt":"El anuncio del tren dice…","options":["La próxima es Tokio","Llegamos tarde","Cierre de puertas"],"correctIndex":0,"explanation":"つぎ = próximo/siguiente."},{"id":"e5","kind":"quiz","prompt":"¿Cómo preguntas dónde está la estación?","options":["駅はどこですか。","駅をください。","駅です。"],"correctIndex":0,"explanation":"N は どこですか = ''¿dónde está N?''."},{"id":"e6","kind":"speaking","textJp":"すみません、駅はどこですか。","reading":"すみません、えきはどこですか","meaning":"Disculpe, ¿dónde está la estación?","voice":"Otoya"},{"id":"e7","kind":"write_sentence","prompt":"Pregunta: ¿Dónde está la estación?","hint":"駅 + は + どこ + ですか","accepted":["駅はどこですか","駅はどこですか。","えきはどこですか"],"explanation":"どこ = dónde."},{"id":"e8","kind":"summary","learned":["駅 (estación)","電車 (tren)","～はどこですか","つぎ (siguiente)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (205, 105, 'Pedir un café', 'カフェで', 'Ordena bebidas con cortesía.', 6, 1, 1, '{"activities":[{"id":"c1","kind":"intro_vocab","word":"コーヒー","reading":"こーひー","meaning":"café","example":"コーヒーをおねがいします。"},{"id":"c2","kind":"intro_vocab","word":"ひとつ","reading":"ひとつ","meaning":"uno (cosa)","example":"コーヒーをひとつ。"},{"id":"c3","kind":"intro_grammar","title":"～をおねがいします","pattern":"N を おねがいします","explanation":"Otra forma cortés de pedir, muy usada al ordenar.","example":{"jp":"コーヒーをおねがいします。","reading":"こーひーをおねがいします","meaning":"Un café, por favor."}},{"id":"c4","kind":"quiz","prompt":"¿Cómo pides un café con cortesía?","options":["コーヒーをおねがいします。","コーヒーですか。","コーヒーはどこですか。"],"correctIndex":0,"explanation":"N を おねがいします para ordenar."},{"id":"c5","kind":"speaking","textJp":"コーヒーを ひとつ おねがいします。","reading":"こーひーを ひとつ おねがいします","meaning":"Un café, por favor.","voice":"Kyoko"},{"id":"c6","kind":"write_sentence","prompt":"Pide un café, por favor.","hint":"コーヒー + を + おねがいします","accepted":["コーヒーをおねがいします","コーヒーをおねがいします。"],"explanation":"おねがいします = por favor (al pedir)."},{"id":"c7","kind":"summary","learned":["コーヒー (café)","ひとつ (uno)","～をおねがいします (pedir con cortesía)"]}]}');
